content:
/* Main body layout and template */

html, body {
  font-family: Arial;
  background: #f1f1f1;
  margin: 0px;
  padding: 0px;
}

li {
  display: inline-block;
  zoom: 1;
  *display: inline;
  padding-right: 20px;
}

.item1 { grid-area: header; }
.item2 { grid-area: subheader; }
.item3 { grid-area: main; }
.item4 { grid-area: subfooter; }
.item5 { grid-area: footer; }

.grid-container {
height: 100%;
width: 100%;
display: grid;
grid-template-columns: repeat(6, 1fr);
  grid-template:
    'header header header header header header'
    'subheader subheader subheader subheader subheader subheader'
    'main main main main main main'
    'subfooter subfooter subfooter subfooter subfooter subfooter'
    'footer footer footer footer footer footer';
}

.grid-container > div {
}

.item1{
  background-color: #333;
  top: 0;
	left: 0;
}

/* Style the topnav links */
.item1 a {
  float: left;
  display: block;
  color: #f2f2f2;
  text-align: center;
  padding: 14px 16px;
  text-decoration: none;
}

/* Change color on hover */
.item1 a:hover {
  background-color: #800000;
  color: black;
}

.item2 {
  padding: 200px;
  text-align: left;
  background-image: url(/Images/backgroundhq.jpg);
  background-repeat: no-repeat;
  left: 0%;
  position: center;
}

.item3{
  background-color: #f1f1f1;
  font-size: 15px;
}

.item4{
  background-color: grey;
  padding: 100px;
}

.item5{
  padding: 15px;
  text-align: center;
  background: #ddd;
  position: static;
  bottom: 0;
  left: 0;
}

/* content boxes */

.content {
  background-color: white;
  padding: 20px;
  margin-top: 20px;
}

.content2 {
  background-color: #e6e6e6;
  padding: 20px;
  margin-top: 20px;
}

/* CSS Gallery */

div.gallery {
  border: 1px solid #ccc;
}

div.gallery:hover {
  border: 1px solid #777;
}

div.gallery img {
  height: 400px;
}

div.desc {
  padding: 15px;
  text-align: center;
}

/* CSS Blog */

.post {
  border: 20px solid #bdc4c7;
  padding: 20px;
  width: 80%;
  margin: 20px auto;
  font-family: 'Source Sans Pro', sans-serif;
}

/* Extra small devices (phones, 600px and down) */
@media only screen and (max-width: 600px) {

  html, body {
    font-family: Arial;
    background: #f1f1f1;
    margin: 0px;
    padding: 0px;
    overflow-x: hidden;
  }

  .item1 { grid-area: header; }
  .item2 { grid-area: subheader; }
  .item3 { grid-area: main; }
  .item4 { grid-area: subfooter; }
  .item5 { grid-area: footer; }

  .grid-container {
  height: 100%;
  width: 100%;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
    grid-template:
      'header header header header header header'
      'subheader subheader subheader subheader subheader subheader'
      'main main main main main main'
      'subfooter subfooter subfooter subfooter subfooter subfooter'
      'footer footer footer footer footer footer';
  }

  .grid-container > div {
  }

  /* Style the topnav links */
  .item1 a {
    width: 100%;
  }

  .item2 {
    background-image: url(/Images/bgresponsivesmall.jpg);
    background-repeat: no-repeat;
  }

  .item3 {
    width: 100%;
  }

  div.gallery img {
    width: 100%;
    height: 400px;
  }
}

  @media only screen and (min-width: 600px) and (max-width: 1500px) {

      html, body {
        font-family: Arial;
        background: #f1f1f1;
        margin: 0px;
        padding: 0px;
        overflow-x: hidden;
      }

      .item1 { grid-area: header; }
      .item2 { grid-area: subheader; }
      .item3 { grid-area: main; }
      .item4 { grid-area: subfooter; }
      .item5 { grid-area: footer; }

      .grid-container {
      height: 100%;
      width: 100%;
      display: grid;
      grid-template-columns: repeat(6, 1fr);
        grid-template:
          'header header header header header header'
          'subheader subheader subheader subheader subheader subheader'
          'main main main main main main'
          'subfooter subfooter subfooter subfooter subfooter subfooter'
          'footer footer footer footer footer footer';
      }

      .grid-container > div {
      }

      /* Style the topnav links */
      .item1 a {
        width: 100%;
      }
      .item2 {
        background-image: url(/Images/bgresponsivemedium.jpg);
        background-repeat: no-repeat;
      }
      .item3 {
        width: 100%;
      }

      div.gallery img {
        width: 100%;
        height: 400px;
      }
    }

  @media only screen and (min-width: 1200px) and (max-width: 1600px) {

    .item2 {
      background-image: url(/Images/bglarge.jpg);
      background-repeat: no-repeat;
    }
  }

  @media only screen and (min-width: 1600px) {

    .item2 {
      background-image: url(/Images/bgxxlarge.jpg);
      background-repeat: no-repeat;
    }
  }
